# Export readable, paginated PNG companions for analytical result tables.
# Daily panels, long curve grids and covariance matrices remain CSV plot data.
source("2. Scripts/00_shared/setup.R")
# Remove only files listed as generated by the previous table-image register.
# Otherwise a shorter new table could leave obsolete trailing pages in the gallery.
register_path <- file.path(DATA, "metadata", "table_image_register.csv")
if (file.exists(register_path)) {
  previous <- read.csv(register_path)
  safe <- grepl("^3[.] Outputs/[^/]+/tables_png/[^/]+[.]png$", previous$PNG)
  unlink(previous$PNG[safe])
}
rendered <- list()
for (theme in THEMES) {
  paths <- list.files(file.path(OUTPUT, theme, "csv"), pattern = "[.]csv$", full.names = TRUE)
  for (path in paths) {
    data <- read.csv(path, check.names = FALSE)
    if (!nrow(data) || nrow(data) > 500 || ncol(data) > 30) next
    # Long prose is retained in CSV/report; exclude it from numeric table images.
    keep <- !vapply(data, function(column) is.character(column) && max(nchar(column), na.rm = TRUE) > 100, logical(1))
    data <- data[, keep, drop = FALSE]
    numeric <- vapply(data, is.numeric, logical(1))
    data[numeric] <- lapply(data[numeric], function(column) format(signif(column, 4), trim = TRUE, scientific = FALSE))
    data[] <- lapply(data, function(column) gsub("_", " ", as.character(column), fixed = TRUE))
    # Split wide tables by columns while retaining identifiers in every panel.
    id_columns <- head(which(!numeric), 2)
    remaining <- setdiff(seq_len(ncol(data)), id_columns)
    column_groups <- split(remaining, ceiling(seq_along(remaining) / 6))
    if (!length(column_groups)) column_groups <- list(integer(0))
    for (column_group in seq_along(column_groups)) {
      columns <- unique(c(id_columns, column_groups[[column_group]]))
      for (page in seq_len(ceiling(nrow(data) / 22))) {
        rows <- ((page - 1) * 22 + 1):min(page * 22, nrow(data))
        display <- data[rows, columns, drop = FALSE]
        names(display) <- gsub("_", "\n", names(display), fixed = TRUE)
        title <- paste(tools::file_path_sans_ext(basename(path)), "— rows", min(rows), "to", max(rows), "— columns", column_group)
        grob <- gridExtra::tableGrob(display, rows = NULL,
          theme = gridExtra::ttheme_minimal(base_size = 9, padding = grid::unit(c(3, 3), "mm")))
        combined <- gridExtra::arrangeGrob(grid::textGrob(title, gp = grid::gpar(fontsize = 12)), grob, ncol = 1, heights = c(.07, .93))
        name <- sprintf("%s_p%02d_c%02d.png", tools::file_path_sans_ext(basename(path)), page, column_group)
        destination <- file.path(OUTPUT, theme, "tables_png", name)
        ggsave(destination, combined, width = max(10, length(columns) * 1.8), height = max(3, length(rows) * .38 + 1.8), dpi = 160, bg = "white", limitsize = FALSE)
        rendered[[length(rendered) + 1]] <- data.frame(CSV = path, PNG = destination, First_row = min(rows), Last_row = max(rows))
      }
    }
  }
}
write.csv(bind_rows(rendered), file.path(DATA, "metadata", "table_image_register.csv"), row.names = FALSE)
